  public RetailDocuments(RetailAccess r,CatalogPort catalog,InventoryPort inventory,FinancePort finance,LeadLifecyclePort lifecycle,RetailSalesOrders orders,vn.coreplatform.controlplane.CommunicationCenter communication,CrmNotificationRecipients recipients){this.communication=communication;this.recipients=recipients;this.orders=orders;this.r=r;this.catalog=catalog;this.inventory=inventory;this.finance=finance;this.lifecycle=lifecycle;}
  private String action(String type){return type.startsWith("PURCHASE")?"PURCHASE":Set.of("TRANSFER","COUNT","OTHER_RECEIPT","OTHER_ISSUE","OPENING_STOCK").contains(type)?"STOCK":Set.of("REFUND","OPENING_AR","OPENING_AP").contains(type)?"FINANCE":"SELL";}
  private boolean sale(String type){return Set.of("QUOTE","SALE_ORDER","POS","ISSUE").contains(type);}
  private boolean requiredApproval(String type){return Set.of("QUOTE","PURCHASE_REQUEST","PURCHASE_ORDER","PURCHASE_RETURN","SALE_RETURN","TRANSFER","COUNT","OTHER_ISSUE","REFUND","OPENING_AR","OPENING_AP").contains(type);}
  public List<Map<String,Object>> lines(Authentication a,UUID id){if(orders.exists(a,id))return orders.lines(a,id);return r.db.queryForList("select * from retail.line where tenant_id=? and document_id=? order by position",r.tenant(a),id);}
