  public Object detail(Authentication a,UUID id){r.require(a,"READ");var d=document(a,id);r.gate(a,RetailPermissions.feature(d.get("type").toString()),"VIEW");return present(a,d);}
  public Object contractDetail(Authentication a,UUID id){var d=document(a,id);if(!"QUOTE".equals(d.get("type"))||!"APPROVED".equals(d.get("status")))throw problem("INVALID_CONTRACT","Hồ sơ hợp đồng phải bắt đầu từ báo giá đã duyệt",HttpStatus.NOT_FOUND);return present(a,d);}
  private Map<String,Object> visible(Authentication a,Map<String,Object> d){var out=r.clean(d);if(!r.granular(a,"partners","VIEW_BANK")){var meta=(ObjectNode)r.node(d.get("metadata")).deepCopy();if(meta.path("partnerSnapshot").isObject())((ObjectNode)meta.path("partnerSnapshot")).remove(List.of("bank_name","bank_account","bank_holder"));out.put("metadata",meta);}return out;}
