  /** Bounded delegation: Sales confirmation may post the full accepted quote, never arbitrary issues. */
  @org.springframework.transaction.annotation.Transactional(propagation=org.springframework.transaction.annotation.Propagation.MANDATORY)
  public UUID issueAcceptedQuote(Authentication a,UUID quoteId,UUID orderId,JsonNode shippingInput){
    var selections=shippingInput.path("items");
    r.modules.require(BusinessModules.STOCK);
    r.gate(a,"orders","CREATE");r.gate(a,"orders","RECORD_RESPONSE");
    var quote=document(a,quoteId);var meta=r.node(quote.get("metadata"));
    if(!"QUOTE".equals(quote.get("type"))||!"APPROVED".equals(quote.get("status"))
        ||!"ACCEPTED".equals(meta.path("customerResponse").asText())||quote.get("approver_id")==null)
      throw problem("QUOTE_NOT_ACCEPTED","Báo giá cần được duyệt và khách đồng ý");
    var order=document(a,orderId);
    if(!quoteId.equals(order.get("source_id")))throw problem("INVALID_SOURCE","Đơn không thuộc báo giá");
    var existing=r.db.queryForList("select id from retail.document where tenant_id=? and sales_order_id=? and type='ISSUE' and metadata->>'automaticQuoteFulfillment'=? and status='POSTED'",r.tenant(a),orderId,quoteId.toString());
    if(!existing.isEmpty())return (UUID)existing.getFirst().get("id");
    if(!"APPROVED".equals(order.get("status")))throw problem("ORDER_ALREADY_ISSUED","Đơn đã được xuất hoặc đóng; kiểm tra phiếu hiện có");
    var orderLines=orders.lines(a,orderId);var quoteLines=lines(a,quoteId);
    if(orderLines.size()!=quoteLines.size()||orderLines.stream().anyMatch(l->quoteLines.stream().noneMatch(q->
        Objects.equals(l.get("source_line_id"),q.get("id"))&&decimal(l.get("base_qty")).compareTo(decimal(q.get("base_qty")))==0)))
      throw problem("ORDER_QUOTE_MISMATCH","Đơn hiện có không chứa đầy đủ lượng hàng báo giá; kiểm tra đơn trước khi tự xuất kho");
    var input=r.json.createObjectNode().put("type","ISSUE").put("sourceId",orderId.toString())
      .put("warehouseId",order.get("warehouse_id").toString()).put("partnerId",order.get("partner_id").toString());
    var lines=input.putArray("lines");
    for(var l:orderLines){
      var out=lines.addObject().put("skuId",l.get("sku_id").toString()).put("sourceLineId",l.get("id").toString())
        .put("qty",decimal(l.get("qty"))).put("unit",l.get("unit").toString());
      if(selections.isArray())for(var selection:selections)if(l.get("source_line_id").toString().equals(selection.path("quoteLineId").asText())){
        out.put("lot",selection.path("lot").asText(""));
        if(selection.path("serials").isArray())out.set("serials",selection.path("serials"));
      }
    }
    @SuppressWarnings("unchecked") var saved=(Map<String,Object>)save(a,input,null,true);
    UUID id=UUID.fromString(saved.get("id").toString());
    r.db.update("update retail.document set metadata=metadata || ?::jsonb where tenant_id=? and id=?",r.json.createObjectNode().put("automaticQuoteFulfillment",quoteId.toString()).set("automaticShippingInput",shippingInput).toString(),r.tenant(a),id);
    // Retain live lot, serial and stock checks in the existing posting engine.
    post(a,document(a,id));
    return id;
  }

  /** Project issues are authorized by the EPC warehouse capability; they use the same posting engine. */
  public Object postEpcIssue(Authentication a,UUID id){r.gate(a,"epc-projects","ISSUE_MATERIAL");var d=document(a,id);state(d,"DRAFT");if(!"OTHER_ISSUE".equals(d.get("type"))||!r.node(d.get("metadata")).hasNonNull("epcProjectId"))throw problem("INVALID_EPC_ISSUE","Phiếu không thuộc dự án EPC");post(a,d);return present(a,r.one("document",r.tenant(a),id));}
  private void post(Authentication a,Map<String,Object> d){
    var currentWarehouse=r.warehouse(a,(UUID)d.get("warehouse_id"));if(!Boolean.TRUE.equals(currentWarehouse.get("active")))throw problem("INACTIVE_WAREHOUSE","Kho đã ngừng sử dụng");if(Set.of("POS","ISSUE").contains(d.get("type"))&&"QUARANTINE".equals(currentWarehouse.get("kind")))throw problem("QUARANTINE_WAREHOUSE","Kho cách ly / hàng lỗi không được dùng để bán hàng");
    var t=r.tenant(a);var id=(UUID)d.get("id");var type=d.get("type").toString();var wh=(UUID)d.get("warehouse_id");var ls=lines(a,id);BigDecimal fee=decimal(d.get("fee")),feeRemaining=fee;var meta=r.node(d.get("metadata"));
    BigDecimal weightTotal=BigDecimal.ZERO;String allocation=meta.path("allocationMethod").asText("VALUE");if(!Set.of("VALUE","QUANTITY","WEIGHT").contains(allocation))throw problem("INVALID_ALLOCATION","Cách phân bổ phí không hợp lệ");for(var l:ls)weightTotal=weightTotal.add(allocationWeight(l,allocation));if(fee.signum()>0&&weightTotal.signum()==0)throw problem("COST_ALLOCATION_ZERO","Không có cơ sở phân bổ phí");
    for(int i=0;i<ls.size();i++){
      var l=ls.get(i);var qty=decimal(l.get("base_qty"));BigDecimal cost=BigDecimal.ZERO;
      if(l.get("sales_order_item_id")!=null){var order=document(a,(UUID)d.get("sales_order_id"));if(!Set.of("APPROVED","PARTIAL").contains(order.get("status")))throw problem("SOURCE_CLOSED","Đơn bán không còn nhận xuất hàng");var orig=orders.line(a,(UUID)d.get("sales_order_id"),(UUID)l.get("sales_order_item_id"));var requested=r.db.queryForObject("select sum(base_qty) from retail.line where tenant_id=? and document_id=? and sales_order_item_id=?",BigDecimal.class,t,id,l.get("sales_order_item_id"));if(requested.compareTo(decimal(orig.get("base_qty")).subtract(decimal(orig.get("progress"))).subtract(decimal(orig.get("closed_qty"))))>0)throw problem("ISSUE_EXCEEDED","Xuất vượt phần còn lại của đơn");}
      if(l.get("source_line_id")!=null){var orig=r.one("line",t,(UUID)l.get("source_line_id"));if(Set.of("ISSUE","PURCHASE_RECEIPT").contains(type)){var source=r.one("document",t,(UUID)d.get("source_id"));if(!Set.of("APPROVED","PARTIAL").contains(source.get("status")))throw problem("SOURCE_CLOSED","Đơn nguồn không còn nhận/xuất");var remain=decimal(orig.get("base_qty")).subtract(decimal(orig.get("progress"))).subtract(decimal(orig.get("closed_qty")));if(type.equals("ISSUE")&&qty.compareTo(remain)>0)throw problem("ISSUE_EXCEEDED","Xuất vượt phần còn của đơn");if(type.equals("PURCHASE_RECEIPT")&&(qty.compareTo(remain)>0||decimal(l.get("price")).compareTo(decimal(orig.get("price")))!=0)){r.gate(a,"purchase-receipt","CONFIRM_DISCREPANCY");if(String.valueOf(d.get("reason")).isBlank())throw problem("DISCREPANCY_REASON","Nhận thừa/khác giá cần lý do được xác nhận");}r.db.update("update retail.line set progress=progress+? where tenant_id=? and id=?",qty,t,orig.get("id"));}
        if(Set.of("SALE_RETURN","PURCHASE_RETURN").contains(type)){var returned=r.db.queryForObject("select coalesce(sum(l.base_qty),0) from retail.line l join retail.document d on d.tenant_id=l.tenant_id and d.id=l.document_id where l.tenant_id=? and l.source_line_id=? and d.status='POSTED' and d.type=?",BigDecimal.class,t,orig.get("id"),type);var currentReturn=r.db.queryForObject("select coalesce(sum(base_qty),0) from retail.line where tenant_id=? and document_id=? and source_line_id=?",BigDecimal.class,t,id,orig.get("id"));if(returned.add(currentReturn).compareTo(decimal(orig.get("base_qty")))>0)throw problem("RETURN_EXCEEDED","Lượng trả đã thay đổi, vượt phần còn trả");if(r.node(l.get("sku_snapshot")).path("tracking").asText().equals("SERIAL")){Set<String> sourceSerials=new HashSet<>();r.node(orig.get("serials")).forEach(s->sourceSerials.add(s.asText()));for(var sn:inventory.serials(l,qty))if(!sourceSerials.contains(sn))throw problem("WRONG_SOLD_SERIAL","Serial không đúng serial của giao dịch gốc");}cost=decimal(orig.get("cost")).multiply(qty).divide(decimal(orig.get("base_qty")),8,RoundingMode.HALF_UP);}
      }
      switch(type){
        case "PURCHASE_RECEIPT","OPENING_STOCK","OTHER_RECEIPT" -> {var part=fee.signum()==0?BigDecimal.ZERO:i==ls.size()-1?feeRemaining:money(fee.multiply(allocationWeight(l,allocation)).divide(weightTotal,8,RoundingMode.HALF_UP));feeRemaining=feeRemaining.subtract(part);cost=decimal(l.get("net")).add(part);boolean quarantine=type.equals("PURCHASE_RECEIPT")&&Set.of("FAULTY","QUARANTINE").contains(String.valueOf(l.get("condition")));inventory.inbound(a,d,l,wh,qty,cost,quarantine,type,null);}
        case "POS","ISSUE","OTHER_ISSUE","PURCHASE_RETURN" -> {cost=inventory.outbound(a,d,l,wh,qty,type.equals("OTHER_ISSUE")&&meta.hasNonNull("epcProjectId")?"EPC_ISSUE":type);}
        case "SALE_RETURN" -> {validateReturnLot(a,l);boolean quarantine="QUARANTINE".equals(l.get("condition"));inventory.inbound(a,d,l,wh,qty,cost,quarantine,type,null);}
        case "COUNT" -> cost=countStock(a,d,l);
        default -> {}
      }
      r.db.update("update retail.line set cost=? where tenant_id=? and id=?",cost,t,l.get("id"));
    }
    BigDecimal total=decimal(d.get("total"));
    if(Set.of("POS","ISSUE","OPENING_AR").contains(type)){var open=finance.open(a,d,"AR",total);finance.settlePost(a,d,open,"RECEIPT");}
    if(Set.of("PURCHASE_RECEIPT","OPENING_AP").contains(type)){var open=finance.open(a,d,"AP",total);finance.settlePost(a,d,open,"PAYMENT");}
    if(Set.of("SALE_RETURN","PURCHASE_RETURN").contains(type)){var refund=finance.creditReturn(a,d,total);((ObjectNode)meta).put("refundCredit",refund);r.db.update("update retail.document set metadata=?::jsonb where tenant_id=? and id=?",meta.toString(),t,id);}
    if(type.equals("REFUND"))refund(a,d);
    r.db.update("update retail.document set status='POSTED',posted_at=now(),version=version+1 where tenant_id=? and id=?",t,id);
    if(d.get("source_id")!=null&&Set.of("ISSUE","PURCHASE_RECEIPT").contains(type)){var remaining=r.db.queryForObject("select count(*) from retail.line where tenant_id=? and document_id=? and base_qty>progress+closed_qty",Integer.class,t,d.get("source_id"));update(a,(UUID)d.get("source_id"),remaining>0?"PARTIAL":"COMPLETE");}if(d.get("partner_id")!=null&&Set.of("SALE_ORDER","POS").contains(type))lifecycle.onDealWon(t,(UUID)d.get("partner_id"));
  }
  private BigDecimal countStock(Authentication a,Map<String,Object> d,Map<String,Object> l){
    var t=r.tenant(a);var wh=(UUID)d.get("warehouse_id");var sku=(UUID)l.get("sku_id");var b=inventory.balance(t,wh,sku);
    if(decimal(b.get("qty")).compareTo(decimal(l.get("count_snapshot")))!=0)throw problem("COUNT_SNAPSHOT_CHANGED","Tồn kiểm kê đã thay đổi");
    var track=r.node(l.get("sku_snapshot")).path("tracking").asText();var counted=decimal(l.get("counted_qty"));var avg=inventory.average(t,wh,sku);if(avg.signum()==0)avg=decimal(l.get("price"));
    BigDecimal adjustment=BigDecimal.ZERO;
    if(track.equals("NONE")){var delta=counted.subtract(decimal(b.get("qty")));if(delta.signum()>0){adjustment=avg.multiply(delta);inventory.inbound(a,d,l,wh,delta,adjustment,false,"COUNT_IN",null);}else if(delta.signum()<0)adjustment=inventory.outbound(a,d,l,wh,delta.negate(),"COUNT_OUT").negate();return adjustment;}
    if(track.equals("LOT")){
      var lots=r.node(l.get("count_lots"));Set<String> codes=new HashSet<>();BigDecimal sum=BigDecimal.ZERO;
      for(var item:lots){String code=required(item,"lot",100);if(!codes.add(code))throw problem("DUPLICATE_LOT","Lô đếm bị trùng");var actual=quantity(num(item,"qty",BigDecimal.ZERO));sum=sum.add(actual);var old=r.db.queryForList("select * from retail.lot where tenant_id=? and warehouse_id=? and sku_id=? and code=?",t,wh,sku,code);BigDecimal expected=old.isEmpty()?BigDecimal.ZERO:decimal(old.getFirst().get("qty"));var delta=actual.subtract(expected);var in=new LinkedHashMap<>(l);in.put("lot",code);in.put("expiry",date(item,"expiry"));
        if(delta.signum()>0){var value=avg.multiply(delta);inventory.inbound(a,d,in,wh,delta,value,false,"COUNT_IN",null);adjustment=adjustment.add(value);}else if(delta.signum()<0)adjustment=adjustment.subtract(inventory.outbound(a,d,in,wh,delta.negate(),"COUNT_OUT"));
      }
      var existing=r.db.queryForList("select code from retail.lot where tenant_id=? and warehouse_id=? and sku_id=? and qty>0",t,wh,sku);for(var item:existing)if(!codes.contains(item.get("code")))throw problem("COUNT_LOT_REQUIRED","Cần khai báo số đếm 0 cho lô không còn thực tế");
      if(sum.compareTo(counted)!=0)throw problem("COUNT_LOT_TOTAL","Tổng số đếm các lô phải bằng số đếm SKU");return adjustment;
    }
    var serials=inventory.serials(l,counted);var actual=new HashSet<>(serials);var existing=r.db.queryForList("select serial from retail.serial where tenant_id=? and warehouse_id=? and sku_id=? and location='AVAILABLE'",t,wh,sku);Set<String> old=new HashSet<>();for(var item:existing)old.add(item.get("serial").toString());
    for(var sn:old)if(!actual.contains(sn)){var out=new LinkedHashMap<>(l);out.put("serials",r.json.valueToTree(List.of(sn)).toString());adjustment=adjustment.subtract(inventory.outbound(a,d,out,wh,BigDecimal.ONE,"COUNT_OUT"));}
    for(var sn:actual)if(!old.contains(sn)){var in=new LinkedHashMap<>(l);in.put("serials",r.json.valueToTree(List.of(sn)).toString());inventory.inbound(a,d,in,wh,BigDecimal.ONE,avg,false,"COUNT_IN",null);adjustment=adjustment.add(avg);}return adjustment;
  }
  private BigDecimal allocationWeight(Map<String,Object> l,String method){return switch(method){case "QUANTITY"->decimal(l.get("base_qty"));case "WEIGHT"->decimal(l.get("base_qty")).multiply(decimal(r.node(l.get("sku_snapshot")).path("weight").asText("0")));default->decimal(l.get("net"));};}
  private void validateReturnLot(Authentication a,Map<String,Object> l){if(!"LOT".equals(r.node(l.get("sku_snapshot")).path("tracking").asText()))return;var source=r.one("line",r.tenant(a),(UUID)l.get("source_line_id"));var segs=r.node(source.get("segments"));String code=String.valueOf(l.get("lot"));BigDecimal sold=BigDecimal.ZERO;String expiry="";for(var seg:segs)if(code.equals(seg.path("lot").asText())){sold=sold.add(decimal(seg.path("qty").asText()));expiry=seg.path("expiry").asText();}if(sold.signum()==0||l.get("expiry")==null||!expiry.equals(l.get("expiry").toString()))throw problem("WRONG_RETURN_LOT","Lô trả không thuộc giao dịch gốc");var returned=r.db.queryForObject("select coalesce(sum(l.base_qty),0) from retail.line l join retail.document d on d.tenant_id=l.tenant_id and d.id=l.document_id where l.tenant_id=? and l.source_line_id=? and l.lot=? and d.type='SALE_RETURN' and d.status='POSTED'",BigDecimal.class,r.tenant(a),source.get("id"),code);if(returned.add(decimal(l.get("base_qty"))).compareTo(sold)>0)throw problem("RETURN_LOT_EXCEEDED","Trả vượt lượng đã bán của lô");}
  private void refund(Authentication a,Map<String,Object> d){var t=r.tenant(a);var source=r.one("document",t,(UUID)d.get("source_id"));var amount=decimal(d.get("total"));var already=r.db.queryForObject("select coalesce(sum(total),0) from retail.document where tenant_id=? and source_id=? and type='REFUND' and status='POSTED'",BigDecimal.class,t,source.get("id"));
    if(source.get("type").equals("SALE_RETURN")){if(already.add(amount).compareTo(decimal(r.node(source.get("metadata")).path("refundCredit").asText("0")))>0)throw problem("REFUND_EXCEEDED","Hoàn vượt tiền đã thu hợp lệ của phần trả");}
    else{if(!source.get("status").equals("CLOSED"))throw problem("ORDER_NOT_CLOSED","Đóng phần chưa xuất trước khi hoàn cọc");var advances=r.db.queryForList("select * from retail.payment where tenant_id=? and document_id=? and kind='RECEIPT' order by created_at",t,source.get("id"));var available=advances.stream().map(p->decimal(p.get("amount")).subtract(decimal(p.get("allocated")))).reduce(BigDecimal.ZERO,BigDecimal::add);if(amount.compareTo(available)>0)throw problem("REFUND_EXCEEDED","Hoàn vượt cọc chưa phân bổ");BigDecimal left=amount;for(var p:advances){var take=left.min(decimal(p.get("amount")).subtract(decimal(p.get("allocated"))));r.db.update("update retail.payment set allocated=allocated+? where tenant_id=? and id=?",take,t,p.get("id"));left=left.subtract(take);if(left.signum()==0)break;}}
    if(!Objects.equals(d.get("method"),source.get("method"))&&String.valueOf(d.get("reason")).isBlank())throw problem("REFUND_METHOD_REASON","Hoàn khác phương thức gốc cần lý do");finance.payment(a,(UUID)d.get("branch_id"),(UUID)d.get("partner_id"),(UUID)d.get("id"),"REFUND",amount,d.get("method").toString(),"Hoàn theo "+source.get("number"));
  }
  private void receive(Authentication a,Map<String,Object> d,JsonNode x){
    state(d,"TRANSIT","PARTIAL");if(!"TRANSFER".equals(d.get("type")))throw problem("INVALID_TRANSFER","Không phải phiếu chuyển");var wh=(UUID)d.get("destination_id");r.warehouse(a,wh);var t=r.tenant(a);if(!x.path("lines").isArray()||x.path("lines").isEmpty())throw problem("LINES_REQUIRED","Cần lượng thực nhận");Set<UUID> received=new HashSet<>();
    for(var item:x.path("lines")){var lineId=uuid(item,"lineId");if(!received.add(lineId))throw problem("DUPLICATE_LINE","Dòng nhận bị trùng");var l=r.one("line",t,lineId);if(!d.get("id").equals(l.get("document_id")))throw problem("INVALID_TRANSFER_LINE","Dòng không thuộc phiếu chuyển");var qty=positive(item,"qty");var base=quantity(qty.multiply(decimal(l.get("ratio"))));var previous=decimal(l.get("progress"));if(previous.add(base).compareTo(decimal(l.get("base_qty")))>0)throw problem("RECEIPT_EXCEEDED","Nhận vượt phần đang chuyển");var in=new LinkedHashMap<>(l);in.put("source_line_id",lineId);in.put("serials",item.path("serials").isArray()?item.path("serials").toString():"[]");var segs=new ArrayList<Map<String,Object>>();var skip=previous;var left=base;for(var seg:r.node(l.get("segments"))){var q=decimal(seg.path("qty").asText());var ignored=skip.min(q);skip=skip.subtract(ignored);q=q.subtract(ignored);var take=left.min(q);if(take.signum()>0)segs.add(Map.of("lot",seg.path("lot").asText(),"expiry",seg.path("expiry").asText(),"qty",take));left=left.subtract(take);}
      var value=decimal(l.get("cost")).multiply(base).divide(decimal(l.get("base_qty")),8,RoundingMode.HALF_UP);boolean damaged=item.path("damaged").asBoolean(false);if(damaged)required(x,"reason",1000);inventory.inbound(a,d,in,wh,base,value,damaged,"TRANSFER_RECEIVE",segs);r.db.update("update retail.line set progress=progress+? where tenant_id=? and id=?",base,t,lineId);
    }
    boolean remains=lines(a,(UUID)d.get("id")).stream().anyMatch(l->decimal(l.get("progress")).compareTo(decimal(l.get("base_qty")))<0);update(a,(UUID)d.get("id"),remains?"PARTIAL":"COMPLETE");
  }
